import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long[] cc, oo;
    static long accC, accO;

    static void pull(int node) {
        int left = 2 * node, right = left + 1;
        long m = Math.min(oo[left], cc[right]);
        cc[node] = cc[left] + cc[right] - m;
        oo[node] = oo[left] + oo[right] - m;
    }

    static void build(int node, int l, int r, String s) {
        if (l == r) {
            if (s.charAt(l) == '(') oo[node] = 1;
            else cc[node] = 1;
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node, l, mid, s);
        build(2 * node + 1, mid + 1, r, s);
        pull(node);
    }

    static void flip(int node, int l, int r, int p) {
        if (l == r) {
            long t = cc[node];
            cc[node] = oo[node];
            oo[node] = t;
            return;
        }
        int mid = (l + r) / 2;
        if (p <= mid) flip(2 * node, l, mid, p);
        else flip(2 * node + 1, mid + 1, r, p);
        pull(node);
    }

    static void walk(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) {
            long m = Math.min(accO, cc[node]);
            accC += cc[node] - m;
            accO += oo[node] - m;
            return;
        }
        int mid = (l + r) / 2;
        if (ql <= mid) walk(2 * node, l, mid, ql, qr);
        if (qr > mid) walk(2 * node + 1, mid + 1, r, ql, qr);
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        String s = next();
        long[][] ops = new long[(int) q][3];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = Long.parseLong(next());
            }
        }

        int cn = (int) n;
        cc = new long[4 * cn];
        oo = new long[4 * cn];
        build(1, 0, cn - 1, s);
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            long kind = ops[k][0];
            int x = (int) ops[k][1], y = (int) ops[k][2];
            if (kind == 1) {
                flip(1, 0, cn - 1, x - 1);
            } else {
                if (out.length() > 0) out.append(" ");
                if ((y - x + 1) % 2 == 1) {
                    out.append(-1);
                } else {
                    accC = 0;
                    accO = 0;
                    walk(1, 0, cn - 1, x - 1, y - 1);
                    out.append((accC + 1) / 2 + (accO + 1) / 2);
                }
            }
        }
        System.out.println(out);
    }
}
